def max_sub_array_sum_repeated(arr, n, k):
    def kadane_algorithm(array):
        """Helper function to find the maximum subarray sum using Kadane's algorithm."""
        max_ending_here = max_so_far = array[0]
        for num in array[1:]:
            max_ending_here = max(num, max_ending_here + num)
            max_so_far = max(max_so_far, max_ending_here)
        return max_so_far

    # Case 1: If k == 1, simply apply Kadane's algorithm to the single array
    if k == 1:
        return kadane_algorithm(arr)

    # Calculate the total sum of the array
    array_sum = sum(arr)

    # Case 2: Find the max subarray sum for one copy of the array
    max_single = kadane_algorithm(arr)

    # Case 3: Find the max subarray sum for two concatenated arrays
    max_two = kadane_algorithm(arr * 2)

    # If the total sum of the array is positive, it contributes to the sum in a repeated array
    if array_sum > 0:
        return max(max_single, max_two, max_two + (k - 2) * array_sum)
    else:
        return max(max_single, max_two)

# Example test case
assert max_sub_array_sum_repeated([10, 20, -30, -1], 4, 3) == 30
```

