def find_sum(lst):
    # Create a dictionary to count occurrences of each element
    element_count = {}
    for num in lst:
        if num in element_count:
            element_count[num] += 1
        else:
            element_count[num] = 1

    # Sum all elements, including repeated ones
    return sum(num for num in lst if element_count[num] == 1)

