def merge_dictionaries_three(dict1, dict2, dict3):
    """
    Merges three dictionaries into one. If there are duplicate keys,
    the value from the dictionary appearing later in the arguments will override the earlier one.
    """
    # Create an empty dictionary to hold the merged result
    merged_dict = {}

    # Update the merged dictionary with the contents of each dictionary in order
    for d in (dict1, dict2, dict3):
        merged_dict.update(d)

    return merged_dict

# Test cases
